Translate("frFR", "layo-starstrike", {
	title = "Layo Starstrike",
	subtitle = "Agent du Cercle cénarien",
	found = "Le repos des vaillants",
	hint = [=[Parlez à l'agent du Cercle parmi les tombes du Repos des vaillants.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Layo" },
	sections = {
		{
			title = "Résumé",
			text = [=[Layo Starstrike est l'un des agents du {link:cenarion-circle}Cercle cénarien{/link} à {link:silithus}Silithus{/link}, et il rend compte à {link:rabine-saturna}Rabine Saturna{/link} à {link:moonglade}Reflet-de-Lune{/link}. Il n'était pas encore né quand la grande guerre fut livrée ici. Pourtant il sent que le passé vit encore dans le désert, et il prend garde à ne pas le réveiller.]=],
		},
		{
			title = "Importance",
			text = [=[Le travail de Layo au {link:southwind-village}Village de Sudevent{/link} ouvrit au Cercle une première fenêtre sur le passé de l'ancienne guerre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il surveille le désert depuis le cimetière du {link:valor-s-rest}Repos des vaillants{/link}.
• Il envoya la première trouvaille du Cercle à {link:southwind-village}Sudevent{/link} à l'archiviste {link:umber}Umber{/link}, à {link:moonglade}Reflet-de-Lune{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La ruche de la tour",
			hint = [=[Libérez les esprits du Village de Sudevent et remuez la ruche de sa tour.]=],
			text = [=[Les esprits de {link:southwind-village}Sudevent{/link} gémissent, et la ruche de la tour du village leur répond. Quand on la remua, elle livra une chose étrange : un bloc de chitine silithide en forme de boîte, d'où dépassait le coin d'un vieux livre. Layo espérait que c'était un journal des jours anciens, préservé dans sa coquille.]=],
		},
	},
	mentions = {
		{ text = "Terres désolées" },
		{ text = "Les esprits de {link:southwind-village}Sudevent{/link}" },
		{ text = "La ruche dans la tour" },
		{ text = "{link:umber}Umber{/link}, archiviste" },
	},
	bonds = {
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "son supérieur à Reflet-de-Lune" },
		{ id = "umber", name = "Umber", note = "lit ce qu'il trouve" },
	},
})

Translate("frFR", "ralo-shan-the-eternal-watcher", {
	title = "Ralo'shan l'Éternel veilleur",
	subtitle = "L'Éternel veilleur",
	found = "Le désert à l'est du Fort cénarien",
	hint = [=[Cherchez le veilleur qui se tient seul dans le désert oriental.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Ralo'shan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ralo'shan se tient seul dans le désert, à l'est du {link:cenarion-hold}Fort cénarien{/link}. Il dit que c'est ici que les {link:qiraji}Qiraji{/link} commencèrent leur marche à travers {link:kalimdor}Kalimdor{/link}, il y a près de mille ans. Il est l'un des rares qui demeurent de cette époque, lié à la fois au passé et au présent. Il ne sait pas pourquoi il doit rester. Il sait seulement qu'il le doit.]=],
		},
		{
			title = "Importance",
			text = [=[Ralo'shan a été tué cent fois, et chaque fois il se réveille là où il se tient. Certains le disent maudit. D'autres le disent héraut d'un âge nouveau.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il monte la garde là où commença l'invasion des {link:qiraji}Qiraji{/link}.
• Il avertit que des forces anciennes s'éveillent, et que des cauchemars ont commencé à sortir du {link:emerald-dream}Rêve d'émeraude{/link}.]=],
		},
	},
	bonds = {
		{ id = "baristolth-of-the-shifting-sands", name = "Baristolth des Sables changeants", note = "un autre qui demeure de l'ancienne guerre" },
	},
})

Translate("frFR", "highlord-demitrian", {
	title = "Généralissime Demitrian",
	subtitle = "Serviteur du prince des Vents",
	found = "La Vallée des cristaux, près d'un champ ravagé",
	hint = [=[Cherchez le généralissime qui attend dans le coin nord-ouest du désert.]=],
	allegiance = "Le prince Thunderaan",
	aliases = { "Demitrian" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le généralissime Demitrian attend au nord-ouest de {link:silithus}Silithus{/link}, près d'un champ ravagé. Il enseigne que les {red:old-gods}Dieux très anciens{/red} firent le monde et furent abattus par les titans, qu'il appelle des usurpateurs. Il sert Thunderaan, prince des Vents. Dans les guerres des éléments, dit-il, les lieutenants du seigneur du Feu {red:ragnaros}Ragnaros{/red} trahirent Thunderaan, et Ragnaros l'abattit et se nourrit de son essence. Le peu qui en restait fut enfermé dans un talisman, et le talisman fut brisé en deux.]=],
		},
		{
			title = "Importance",
			text = [=[Demitrian garde la mémoire des anciennes guerres des éléments, que peu de mortels ont entendue. Il ne souffre pas que l'on prononce devant lui le nom du seigneur du Feu.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il enseigne l'histoire des Dieux très anciens et des guerres élémentaires à ceux qui veulent l'écouter.
• Il attend quelqu'un qui puisse restaurer le prince des Vents.]=],
		},
	},
	mentions = {
		{ text = "Thunderaan le Cherchevent" },
	},
})

Translate("frFR", "aendel-windspear", {
	title = "Aendel Windspear",
	subtitle = "Un fantôme de Sudevent",
