	allegiance = "Cercle cénarien",
	aliases = { "Aendel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Parmi les ruines du {link:southwind-village}Village de Sudevent{/link} se tient le fantôme d'une femme. Elle regarde les vivants avec méfiance et ne parle pas. Pourtant elle commerce. À ceux qui ont gagné la confiance du {link:cenarion-circle}Cercle cénarien{/link}, elle offre des patrons d'armures de cuir, dont certains portent le nom des silithides des ruches et des créatures du désert.]=],
		},
		{
			title = "Importance",
			text = [=[De tous les morts de {link:southwind-village}Sudevent{/link}, Aendel est la seule à traiter avec les vivants.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun écrit ne dit qui était Aendel de son vivant, ni comment elle en vint à s'attarder dans les ruines.]=],
		},
	},
})
